function LanguageMap() {
  const { state, update } = useLearner();
  const [query, setQuery] = useState("");
  const filtered = targetLanguageIds.filter((id) => `${languages[id].name} ${languages[id].native}`.toLowerCase().includes(query.toLowerCase()));
  const pick = (id: LanguageId) => { update({ target: id }); playSound("pin"); };
  return <div className="screen-stack"><ScreenHeading eyebrow="Communities, not borders" title="A multilingual India" description="Orbit the atlas and choose a community marker. Languages are not borders — speakers move, overlap, and live far beyond any pin." /><div className="map-layout"><div className="india-map glass-card map-canvas" role="img" aria-label="Three-dimensional map of India with ten language-community markers. An equivalent searchable list follows."><ClientStage kind="map" /></div><section className="map-list glass-card"><label className="field-label">Search the equivalent text list<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search language" /></label><ul>{filtered.map((id) => <li key={id}><button type="button" data-sound="silent" className={state.target === id ? "active" : ""} onClick={() => pick(id)}><span style={{ background: languages[id].accent }} /><div><b>{languages[id].native} · {languages[id].name}</b><p>{languages[id].script}. A community marker, not a claim of exclusive territory.</p></div></button></li>)}</ul></section></div></div>;
}

function OfflineManager() {
  const { state } = useLearner(); const key = `lufo-pack-${state.target}`; const [downloaded, setDownloaded] = useState(false); const [status, setStatus] = useState("Not downloaded");
  useEffect(() => { setDownloaded(localStorage.getItem(key) === "ready"); setStatus(localStorage.getItem(key) === "ready" ? "Available from local app data" : "Not downloaded"); }, [key]);
  const download = async () => { setStatus("Preparing local pack…"); localStorage.setItem(key, "ready"); if ("serviceWorker" in navigator) await navigator.serviceWorker.register("/sw.js").catch(() => undefined); setDownloaded(true); setStatus("Local pack ready; offline launch still depends on browser PWA support and prior page caching."); };
  return <div className="screen-stack"><ScreenHeading eyebrow="Local-first learning" title="Offline packs" description="Core authored content ships with the app. A pack records offline intent and registers the cache worker; browser storage and PWA support vary." /><section className="download-card glass-card"><div className={`pack-art motif-${languages[state.target].motif}`}><Download /></div><div><span className="eyebrow">{languages[state.target].native} · {languages[state.target].name}</span><h2>{downloaded ? "Pack available on this device" : "Download local learning pack"}</h2><p>Includes lessons, 5 stories, 13 games, Script Studio data, flashcards, memes, scripted tutor routes, and local progress.</p><ul><li><Check />Authored learning data</li><li><Check />Local progress and saved words</li><li><X />Live AI, cloud sync, and arbitrary translation</li><li><CircleHelp />Browser speech only if the device has a matching voice</li></ul><div className="row-actions"><button className="primary-button" onClick={download} disabled={downloaded}><Download />{downloaded ? "Pack ready" : "Prepare offline pack"}</button>{downloaded && <button className="soft-button" onClick={() => { localStorage.removeItem(key); setDownloaded(false); setStatus("Removed local pack marker. Browser cache may be cleared in site settings."); }}><Trash2 />Remove</button>}</div><p role="status">{status}</p></div></section><div className="honest-state"><WifiOff /><div><strong>Offline scope</strong><p>The current service worker caches visited pages and core assets rather than guaranteeing every route before it has been opened. The “pack” marker does not misrepresent full native-app download management. Live services remain unavailable offline.</p></div></div></div>;
}

function SettingsScreen() {
  const { state, update, updateAccess, exportData, importData, deleteData } = useLearner(); const [importStatus, setImportStatus] = useState(""); const [confirmDelete, setConfirmDelete] = useState(false);
  return <div className="screen-stack"><ScreenHeading eyebrow="Preferences, privacy, and control" title="Settings" description="Progress stays on this device, in a separate pocket for each signed-in account and for guest exploration. No analytics tracker or chat upload is active." /><div className="settings-grid"><SettingsGroup title="Languages" icon={<LanguagesIcon />}><label className="field-label">Target language<select value={state.target} onChange={(event) => update({ target: event.target.value as LanguageId })}>{targetLanguageIds.map((id) => <option key={id} value={id}>{languages[id].name}</option>)}</select></label><label className="field-label">Primary explanation<select value={state.primaryFamiliar} onChange={(event) => update({ primaryFamiliar: event.target.value as FamiliarLanguageId })}>{state.familiar.map((id) => <option key={id} value={id}>{familiarLanguages.find((item) => item.id === id)?.name}</option>)}</select></label><label className="field-label">Meaning visibility<select value={state.lensMode} onChange={(event) => update({ lensMode: event.target.value as typeof state.lensMode })}><option value="hidden">Hidden until requested</option><option value="peek">Peek on request</option><option value="visible">Always visible</option><option value="side-by-side">Side-by-side in stories</option></select></label><Toggle label="Show transliteration" detail="Separate from translation" checked={state.showTransliteration} onChange={(value) => update({ showTransliteration: value })} /></SettingsGroup><SettingsGroup title="Appearance" icon={<Sun />}><label className="field-label">Appearance<select value={state.access.theme} onChange={(event) => updateAccess({ theme: event.target.value as "dark" | "light" | "system" })}><option value="dark">Dark</option><option value="light">Light</option><option value="system">System</option></select></label><Toggle label="Reduced motion" detail="No animated portal or particles" checked={state.access.reducedMotion} onChange={(value) => updateAccess({ reducedMotion: value })} /><Toggle label="High contrast" detail="Stronger focus and boundaries" checked={state.access.highContrast} onChange={(value) => updateAccess({ highContrast: value })} /><Link className="soft-button" href="/app/access"><Accessibility />Open all access controls</Link></SettingsGroup><SettingsGroup title="LUFO memory" icon={<MoonStar />}><p>Optional memory is local only. It currently contains {state.memories.length} item(s).</p><label className="field-label">Add a non-sensitive preference<input placeholder="e.g. I like food stories" onKeyDown={(event) => { if (event.key === "Enter" && event.currentTarget.value.trim()) { update({ memories: [...state.memories, event.currentTarget.value.trim()] }); event.currentTarget.value = ""; } }} /></label><ul className="memory-list-settings">{state.memories.map((item, index) => <li key={`${item}-${index}`}>{item}<button aria-label={`Delete memory ${item}`} onClick={() => update({ memories: state.memories.filter((_, i) => i !== index) })}><X /></button></li>)}</ul><button className="soft-button" onClick={() => update({ memories: [] })} disabled={!state.memories.length}><Trash2 />Delete LUFO memory</button></SettingsGroup><SettingsGroup title="Your data" icon={<ShieldCheck />}><p>Stored locally: preferences, per-language progress, review history, saved words, story pages, local memes, and optional LUFO memory.</p><button className="soft-button" onClick={exportData}><FileDown />Export JSON</button><label className="soft-button file-input"><Upload />Import JSON<input type="file" accept="application/json" onChange={async (event) => { const file = event.target.files?.[0]; if (file) setImportStatus(importData(await file.text()).message); }} /></label><p role="status">{importStatus}</p>{!confirmDelete ? <button className="danger-button" onClick={() => setConfirmDelete(true)}><Trash2 />Delete local learning data</button> : <div className="delete-confirm"><p>This removes all LUFO learning data from this browser.</p><button className="danger-button" onClick={deleteData}>Confirm delete</button><button className="soft-button" onClick={() => setConfirmDelete(false)}>Cancel</button></div>}</SettingsGroup></div></div>;
}

function StickerAlbum() { const { state } = useLearner(); const xp = state.progress[state.target].xp; const stickers = ["Curious comet", "Kind kite", "Story lantern", "Script spark", "Gentle streak", "Brave bubble", "Quiet quest", "Helpful hat"]; return <div className="screen-stack"><ScreenHeading eyebrow="Predictable rewards · no random purchases" title="Sticker album" description="Earn one original sticker for each 20 XP. Disabling surprise effects never changes educational access." /><div className="sticker-grid">{stickers.map((item, index) => { const unlocked = xp >= (index + 1) * 20; return <article key={item} className={`sticker-card ${unlocked ? "unlocked" : "locked"}`}><div className={`sticker-art sticker-${index + 1}`} aria-hidden="true"><span>{unlocked ? "L" : "?"}</span><i /></div><h2>{item}</h2><p>{unlocked ? `Earned with real activity in ${languages[state.target].name}.` : `Unlock at ${(index + 1) * 20} XP.`}</p></article>; })}</div></div>; }

function BuddyChallenges() { const [players, setPlayers] = useState(["Learner 1", "Learner 2"]); const [scores, setScores] = useState([0, 0]); const [turn, setTurn] = useState(0); return <div className="narrow-screen"><ScreenHeading eyebrow="Same-device buddy · pass and play" title="A challenge beside you" description="This is not remote multiplayer and does not imply a synced friend. Hand the device to a real buddy when each turn ends." /><section className="buddy-card glass-card"><span className="status-pill demo">Same-device mode</span><div className="buddy-score">{players.map((player, index) => <div key={index} className={turn === index ? "active" : ""}><input aria-label={`Player ${index + 1} name`} value={player} onChange={(event) => setPlayers(players.map((item, i) => i === index ? event.target.value : item))} /><strong>{scores[index]}</strong><span>points</span></div>)}</div><h2>{players[turn]}’s turn</h2><p>Choose a small challenge, then pass the device.</p><div className="choice-cards"><button onClick={() => { setScores(scores.map((score, index) => index === turn ? score + 5 : score)); setTurn((turn + 1) % 2); }}>Recall a saved word · +5</button><button onClick={() => { setScores(scores.map((score, index) => index === turn ? score + 8 : score)); setTurn((turn + 1) % 2); }}>Read a story page · +8</button></div><button className="soft-button" onClick={() => window.print()}><Share2 />Print/export challenge card</button></section></div>; }

function Community() {
  const [entries, setEntries] = useState<{ title: string; body: string; attribution: string }[]>([]); const [title, setTitle] = useState(""); const [body, setBody] = useState(""); const [consent, setConsent] = useState(false);
  useEffect(() => { try { setEntries(JSON.parse(localStorage.getItem("lufo-local-contributions") ?? "[]")); } catch { /* ignore parse error */ } }, []);
  const save = () => { const next = [...entries, { title, body, attribution: "Private attribution" }]; setEntries(next); localStorage.setItem("lufo-local-contributions", JSON.stringify(next)); setTitle(""); setBody(""); setConsent(false); };
  return <div className="screen-stack"><ScreenHeading eyebrow="Contribution workspace · local only" title="Share knowledge carefully" description="Entries are saved on this device. They are not publicly submitted, reviewed, or added to lessons. Export is available for a future moderated workflow." /><div className="community-grid"><form className="glass-card contribution-form" onSubmit={(event) => { event.preventDefault(); save(); }}><span className="status-pill demo">Saved on this device</span><h2>Draft a cultural note or correction</h2><label className="field-label">Title<input required value={title} onChange={(event) => setTitle(event.target.value)} /></label><label className="field-label">Contribution<textarea required value={body} onChange={(event) => setBody(event.target.value)} /></label><label className="check-label"><input required type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} />I created this or have permission to contribute it, and understand it stays local.</label><button className="primary-button" disabled={!consent}><Save />Save local draft</button></form><section className="glass-card"><h2>Local drafts</h2>{entries.length ? <ul className="contribution-list">{entries.map((entry, index) => <li key={index}><b>{entry.title}</b><p>{entry.body}</p><span>Unreviewed learner-created content · Local only</span><button aria-label={`Delete ${entry.title}`} onClick={() => { const next = entries.filter((_, i) => i !== index); setEntries(next); localStorage.setItem("lufo-local-contributions", JSON.stringify(next)); }}><Trash2 /></button></li>)}</ul> : <EmptyState title="No contributions yet" text="Your local drafts will appear here." />}</section></div></div>;
}

function TeacherPreview() { return <div className="screen-stack"><ScreenHeading eyebrow="Demonstration view · privacy-respecting" title="Parent / teacher preview" description="This view uses labeled demonstration data. A future account backend would be required for real remote educator access." /><div className="honest-state"><ShieldCheck /><div><strong>Private by default</strong><p>Chats, recordings, optional memory, and access preferences are not shown here.</p></div></div><div className="metric-grid"><Metric icon={<BookOpen />} value="4" label="Activities" detail="Demonstration data" /><Metric icon={<LanguagesIcon />} value="12" label="Words practiced" detail="Demonstration data" /><Metric icon={<RefreshCw />} value="3" label="Review needs" detail="Demonstration data" /><Metric icon={<Clock3 />} value="18m" label="Learning time" detail="Demonstration data" /></div><section className="glass-card"><h2>Skills preview</h2><p className="demo-watermark">DEMONSTRATION DATA</p><ul className="skill-list"><li><CheckCircle2 /><span>Recognized everyday greetings</span><b>Practiced</b></li><li><BookOpen /><span>Read two supported pages</span><b>Practiced</b></li><li><PenLine /><span>Identified three script forms</span><b>Needs review</b></li></ul></section></div>; }

function SceneVocabulary() { const { state } = useLearner(); const [selected, setSelected] = useState("water"); const objects = ["water", "food", "friend"]; return <div className="screen-stack"><ScreenHeading eyebrow="Authored scene · non-camera baseline" title="Look around with words" description="Choose an illustrated object manually. This is not live object detection or spatial AR, and it requests no camera permission." /><div className="scene-layout"><div className="market-scene glass-card" role="img" aria-label="Stylized market scene with selectable water, food, and friend locations. Buttons after the scene provide the same information."><div className="scene-sky" /><div className="scene-stall" /><button className="object-hotspot water" onClick={() => setSelected("water")} aria-label="Select water in scene" /><button className="object-hotspot food" onClick={() => setSelected("food")} aria-label="Select food in scene" /><button className="object-hotspot friend" onClick={() => setSelected("friend")} aria-label="Select friend in scene" /></div><aside><div className="object-list" aria-label="Nonvisual scene objects">{objects.map((id) => <button key={id} className={selected === id ? "active" : ""} onClick={() => setSelected(id)}>{getConcept(id).values.en}</button>)}</div><LensCard conceptId={selected} activity="scene" /></aside></div></div>; }

function TestingDisclosure() { return <section className="testing-disclosure glass-card"><div><span className="eyebrow">Accessibility status</span><h2>Designed toward WCAG 2.2 AA; not certified</h2></div><p>Implemented and build-tested: semantic routes, skip link, keyboard controls, focus-visible styles, reduced motion/transparency, high contrast, text alternatives, captions-first content, untimed game paths, and responsive reflow.</p><p>Not completed in this environment: participant testing with disabled learners, named screen-reader/browser matrices, native braille hardware tests, qualified ISL video production, full manual WCAG audit, or ten-language assistive-technology pronunciation verification.</p></section>; }

function NotFound() { return <div className="narrow-screen"><section className="empty-state glass-card"><span>404</span><h1>This path drifted off course</h1><p>Your progress is safe. Return to the learning path.</p><Link className="primary-button" href="/app/learn">Back to learning</Link></section></div>; }
function ScreenHeading({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: React.ReactNode }) { return <header className="screen-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{actions && <div className="screen-actions">{actions}</div>}</header>; }
function DailyQuest() { const { state } = useLearner(); const done = state.progress[state.target].savedConcepts.length; return <section className="daily-quest glass-card"><div className="quest-icon"><Star /></div><div><span className="eyebrow">Today’s flexible quest</span><h2>Save two useful words</h2><p>Actual event progress · {Math.min(done, 2)} of 2</p><div className="quest-bar"><i style={{ width: `${Math.min(done / 2, 1) * 100}%` }} /></div></div><Link href="/app/learn" className="soft-button">Choose a lesson</Link></section>; }
function wrapCanvasText(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, maxWidth: number, lineHeight: number) { const words = text.split(" "); let line = ""; for (const word of words) { const test = `${line}${word} `; if (ctx.measureText(test).width > maxWidth && line) { ctx.fillText(line, x, y); line = `${word} `; y += lineHeight; } else line = test; } ctx.fillText(line, x, y); }
